DROP TABLE IF EXISTS public.mel_reach_targets;
CREATE TABLE public.mel_reach_targets (
  cluster text, district text, month date,
  monthly_target numeric, monthly_shgs numeric,
  monthly_yiw numeric, monthly_female numeric, monthly_pwds numeric
);
DROP TABLE IF EXISTS public.mel_production_targets;
CREATE TABLE public.mel_production_targets (
  district text, y3_target numeric, shg numeric, season text,
  season_start date, season_end date, expected_jobs numeric,
  poultry numeric, goats numeric, horticulture numeric, dairy numeric, total_achieved numeric
);
